1	const APPLICATION_STATE_STORE_NAME = 'application-state';
2	const {
3	    APPLICATION_STATE_READ_CHANNEL,
4	    APPLICATION_STATE_REMOVE_CHANNEL,
5	    APPLICATION_STATE_WRITE_CHANNEL,
6	} = require('./ipc_channels');
7	
8	function requireKey(key) {
9	    if (typeof key !== 'string' || key.length === 0) throw new Error('Application-state key is required');
10	
11	    return key;
12	}
13	
14	function requireValue(value) {
15	    if (typeof value !== 'string') throw new Error('Application-state value must be a string');
16	
17	    return value;
18	}
19	
20	/** Create renderer application persistence separately from desktop configuration. */
21	function createApplicationStateStore(Store) {
22	    return new Store({ accessPropertiesByDotNotation: false, name: APPLICATION_STATE_STORE_NAME });
23	}
24	
25	function readApplicationState(store, key) {
26	    if (key === null) return store.store;
27	
28	    return store.get(requireKey(key), null);
29	}
30	
31	function writeApplicationState(store, key, value) {
32	    const storedKey = requireKey(key);
33	    const storedValue = requireValue(value);
34	    store.set(storedKey, storedValue);
35	
36	    return storedValue;
37	}
38	
39	function removeApplicationState(store, key) {
40	    store.delete(requireKey(key));
41	}
42	
43	function registerApplicationStateBridge(ipcMain, store) {
44	    ipcMain.handle(APPLICATION_STATE_READ_CHANNEL, (_event, key) => readApplicationState(store, key));
45	    ipcMain.handle(APPLICATION_STATE_WRITE_CHANNEL, (_event, key, value) => writeApplicationState(store, key, value));
46	    ipcMain.handle(APPLICATION_STATE_REMOVE_CHANNEL, (_event, key) => removeApplicationState(store, key));
47	}
48	
49	module.exports = {
50	    APPLICATION_STATE_STORE_NAME,
51	    createApplicationStateStore,
52	    readApplicationState,
53	    registerApplicationStateBridge,
54	    removeApplicationState,
55	    writeApplicationState,
56	};
